# Writes the hedra command files of Sky Raid's world and game pieces (everything but the hero biplane,
# which has its own p1/p2/p3 files in models/plane). Run from models/env:
#   /usr/bin/python3 make_env.py
# hedra: up Z, front -Y (the GLB comes out Y up, front +Z: towards the camera, i.e. DOWN the screen).
# Colours are exact Fantasy 24 hexes (sRGB 0..1), so the bake snaps them with colour error 0.000.
#
# Terrain: eight tiles of 16 x 6 m (x -8..8, y -3..3, the ground at z 0), two of each kind (fields,
# village, woods, river), every one different (seeded). Each tile is a partition of its rectangle into
# flat patches (no overlaps: a coplanar overlay fights the surface at splat size), with hedges, trees,
# houses on top. A hedgerow runs along every tile's far edge, so the seams read as field boundaries.
import math, random

HEX = {
    "Grass": "39571c", "Pasture": "a58c27", "Moss": "1f240a",
    "Leaf": "39571c", "Pine": "183f39",
    "Wheat": "efac28", "WheatRow": "a58c27",
    "Soil": "724113", "Furrow": "45230d", "Sand": "ab5c1c", "Trunk": "45230d", "Wicker": "724113",
    "Water": "276468", "Ripple": "3c9f9c",
    "Roof": "9b1a0a", "Band": "550f0a",
    "Wall": "efd8a1", "Stone": "927e6a", "Lane": "927e6a", "Plank": "684c3c",
    "Canvas": "efd8a1", "Paint": "ef692f", "Gold": "efac28",
    "Metal": "684c3c", "Dark": "392a1c", "Steel": "927e6a",
    "Glow": "ef3a0c", "Hot": "efac28", "Core": "efd8a1", "Flame": "ef692f",
    "Shot": "efd8a1", "Foe": "efd8a1", "Rotor": "3c9f9c",
}
EMIT = {"Glow", "Hot", "Core", "Flame", "Shot", "Foe"}


def mat(name):
    h = HEX[name]
    r, g, b = (int(h[i:i + 2], 16) / 255 for i in (0, 2, 4))
    s = f"material new {name} --base-color {r:.3f} {g:.3f} {b:.3f} --no-slot"
    if name in EMIT:
        s += f" --emission {r:.3f} {g:.3f} {b:.3f}"
    return s


class Model:
    def __init__(self, name, comment, mats):
        self.name = name
        self.n = 0
        self.L = [f"# {comment}", "# Generated by make_env.py.", "new"] + [mat(m) for m in mats]

    def nm(self, base):
        self.n += 1
        return f"{base}{self.n}"

    def add(self, *lines):
        self.L += list(lines)

    def rect(self, x0, x1, y0, y1, m, z=0.0):
        """a flat patch (faces +Z)"""
        n = self.nm("P")
        self.add(f"add mesh plane --name {n} --size 1 --location {(x0 + x1) / 2:.3f} {(y0 + y1) / 2:.3f} {z:.3f}",
                 f"scale {x1 - x0:.3f} {y1 - y0:.3f} 1", "apply --scale", f"material assign {m}")

    def box(self, x, y, z, sx, sy, sz, m, base="B", rot=None, drop_bottom=False, lumpy=0.0, seed=1):
        n = self.nm(base)
        self.add(f"add mesh cube --name {n} --size 1 --location {x:.3f} {y:.3f} {z:.3f}",
                 f"scale {sx:.3f} {sy:.3f} {sz:.3f}", "apply --scale")
        if rot:
            self.add(f"set rotation {rot[0]} {rot[1]} {rot[2]}", "apply --rotation")
        if drop_bottom or lumpy:
            self.add(f"select {n}", f"active {n}", "mode edit")
            if lumpy:
                cuts = max(1, int(max(sx, sy) / 0.35))
                self.add("select all", f"subdivide --cuts {min(cuts, 12)}", 'select vert where "pos.z > -0.01"',
                         f"randomize --amount {lumpy} --seed {seed}")
            if drop_bottom:
                self.add('select face where "normal.z < -0.9"', "delete only-faces")
            self.add("mode object")
        self.add(f"select {n}", f"material assign {m}")
        return n

    def tree(self, x, y, r, rnd, m="Leaf"):
        """a round tree: an icosahedron canopy on a short trunk"""
        h = r * 1.6
        n = self.nm("T")
        self.add(f"add mesh cylinder --name {n} --vertices 6 --radius 0.08 --depth {h * 0.6:.3f} --location {x:.3f} {y:.3f} {h * 0.3:.3f}",
                 f"select {n}", f"active {n}", "mode edit", 'select face where "normal.z < -0.9"', "delete only-faces",
                 "mode object", "material assign Trunk")
        c = self.nm("C")
        self.add(f"add mesh ico-sphere --name {c} --subdivisions 1 --radius {r:.3f} --location {x:.3f} {y:.3f} {h * 0.55 + r * 0.6:.3f}",
                 f"set rotation {rnd.uniform(0, 60):.1f} {rnd.uniform(0, 60):.1f} {rnd.uniform(0, 360):.1f}", "apply --rotation",
                 "scale 1 1 0.85", "apply --scale", f"material assign {m}")

    def pine(self, x, y, h):
        n = self.nm("N")
        self.add(f"add mesh cone --name {n} --vertices 6 --radius1 {h * 0.36:.3f} --radius2 0 --depth {h:.3f} --location {x:.3f} {y:.3f} {h / 2 + 0.12:.3f}",
                 f"select {n}", f"active {n}", "mode edit", 'select face where "normal.z < -0.9"', "delete only-faces",
                 "mode object", "material assign Pine")
        t = self.nm("K")
        self.add(f"add mesh cylinder --name {t} --vertices 5 --radius 0.07 --depth 0.16 --location {x:.3f} {y:.3f} 0.08",
                 "material assign Trunk")

    def hedge(self, x0, x1, y0, y1, seed):
        """a hedgerow along a border: a lumpy low box (0.3 wide, 0.3 tall)"""
        if x1 - x0 > y1 - y0:
            self.box((x0 + x1) / 2, (y0 + y1) / 2, 0.15, x1 - x0, 0.3, 0.3, "Leaf", "H", drop_bottom=True, lumpy=0.05, seed=seed)
        else:
            self.box((x0 + x1) / 2, (y0 + y1) / 2, 0.15, 0.3, y1 - y0, 0.3, "Leaf", "H", drop_bottom=True, lumpy=0.05, seed=seed)

    def house(self, x, y, w, d, along_x=True, wall="Wall", roof="Roof", chimney=True):
        """walls w (along the ridge) x d x 0.5, a gable roof overhanging 0.06, a chimney"""
        sx, sy = (w, d) if along_x else (d, w)
        self.box(x, y, 0.25, sx, sy, 0.5, wall, "W", drop_bottom=True)
        n = self.nm("R")
        rot = "0 -90 0" if along_x else "0 -90 90"
        self.add(f"add mesh cylinder --name {n} --vertices 3 --radius 1 --depth {w + 0.12:.3f} --location {x:.3f} {y:.3f} 0 --rotation {rot}",
                 "apply --rotation")
        hy = (d / 2 + 0.07) / 0.866
        hz = 0.45 / 1.5
        if along_x:
            self.add(f"scale 1 {hy:.3f} {hz:.3f}", "apply --scale")
        else:
            self.add(f"scale {hy:.3f} 1 {hz:.3f}", "apply --scale")
        self.add(f"translate 0 0 {0.5 + 0.5 * hz:.3f}", "apply --location",
                 f"select {n}", f"active {n}", "mode edit", 'select face where "normal.z < -0.9"', "delete only-faces",
                 "mode object", f"material assign {roof}")
        if chimney:
            cx, cy = (x + w * 0.28, y) if along_x else (x, y + w * 0.28)
            self.box(cx, cy + (0.08 if along_x else 0), 0.86, 0.14, 0.14, 0.3, "Stone", "Ch", drop_bottom=True)

    def done(self, glb, join=False):
        self.add("select all", "shade flat", f"export {glb}.glb")
        with open(f"{self.name}.txt", "w") as f:
            f.write("\n".join(self.L) + "\n")


def striped(m, x0, x1, y0, y1, a, b, w, along_x):
    """a field of alternating strips (wheat rows, furrows), each w wide"""
    if along_x:
        n = max(2, round((y1 - y0) / w))
        for i in range(n):
            m.rect(x0, x1, y0 + (y1 - y0) * i / n, y0 + (y1 - y0) * (i + 1) / n, a if i % 2 == 0 else b)
    else:
        n = max(2, round((x1 - x0) / w))
        for i in range(n):
            m.rect(x0 + (x1 - x0) * i / n, x0 + (x1 - x0) * (i + 1) / n, y0, y1, a if i % 2 == 0 else b)


def field_cell(m, x0, x1, y0, y1, kind, rnd):
    if kind == "wheat":
        striped(m, x0, x1, y0, y1, "Wheat", "WheatRow", 0.42, rnd.random() < 0.5)
        if rnd.random() < 0.6 and x1 - x0 > 1.6:
            for k in range(rnd.randint(1, 3)):
                hx, hy = rnd.uniform(x0 + 0.5, x1 - 0.5), rnd.uniform(y0 + 0.5, y1 - 0.5)
                n = m.nm("Hay")
                m.add(f"add mesh cylinder --name {n} --vertices 7 --radius 0.24 --depth 0.26 --location {hx:.2f} {hy:.2f} 0.13",
                      f"select {n}", f"active {n}", "mode edit", 'select face where "normal.z < -0.9"', "delete only-faces",
                      "mode object", "material assign Hay")
    elif kind == "plough":
        striped(m, x0, x1, y0, y1, "Soil", "Furrow", 0.34, rnd.random() < 0.5)
    elif kind == "pasture":
        m.rect(x0, x1, y0, y1, "Pasture")
    else:
        m.rect(x0, x1, y0, y1, "Grass")
        if rnd.random() < 0.5 and (x1 - x0) > 1.5:
            for k in range(rnd.randint(1, 2)):
                m.tree(rnd.uniform(x0 + 0.5, x1 - 0.5), rnd.uniform(y0 + 0.5, y1 - 0.5), rnd.uniform(0.3, 0.42), rnd)


def splits(rnd, a, b, n, minw):
    while True:
        cuts = sorted(rnd.uniform(a + minw, b - minw) for _ in range(n))
        xs = [a] + cuts + [b]
        if all(xs[i + 1] - xs[i] >= minw for i in range(len(xs) - 1)):
            return [round(v, 2) for v in xs]


def far_hedge(m, seed, gaps=()):
    """the hedgerow along the tile's far edge (y 2.7..3.0), broken at the gaps (x ranges)"""
    xs = [-8.0]
    for g0, g1 in gaps:
        xs += [g0, g1]
    xs += [8.0]
    for i in range(0, len(xs), 2):
        if xs[i + 1] - xs[i] > 0.4:
            m.hedge(xs[i], xs[i + 1], 2.7, 3.0, seed + i)


TILE_MATS = ["Grass", "Pasture", "Moss", "Leaf", "Pine", "Wheat", "WheatRow", "Hay", "Soil", "Furrow", "Sand", "Trunk",
             "Water", "Ripple", "Roof", "Wall", "Stone", "Lane", "Plank"]
HEX["Hay"] = "efac28"

# ---------------------------------------------------------------- fields
def fields(name, seed):
    rnd = random.Random(seed)
    m = Model(name, f"Terrain tile {name}: a 16 x 6 m patchwork of wheat, ploughed land, meadow and pasture with "
                    "hedgerows on the borders, lone trees and haystacks.", TILE_MATS)
    xs = splits(rnd, -8, 8, 3, 2.6)
    kinds = ["wheat", "plough", "meadow", "pasture"]
    last = None
    for i in range(len(xs) - 1):
        x0, x1 = xs[i], xs[i + 1]
        ys = [-3.0, 2.7] if rnd.random() < 0.35 else [-3.0, round(rnd.uniform(-1.4, 1.2), 2), 2.7]
        for j in range(len(ys) - 1):
            k = rnd.choice([q for q in kinds if q != last])
            last = k
            field_cell(m, x0, x1, ys[j], ys[j + 1], k, rnd)
            if j > 0:
                m.hedge(x0 + 0.15, x1 - 0.15, ys[j] - 0.15, ys[j] + 0.15, seed + 50 + i)
        if i > 0:
            m.hedge(x0 - 0.15, x0 + 0.15, -3.0, 2.7, seed + i)
            if rnd.random() < 0.7:
                m.tree(x0, rnd.uniform(-2.4, 2.2), rnd.uniform(0.38, 0.5), rnd)
    m.rect(-8, 8, 2.7, 3.0, "Grass")
    far_hedge(m, seed, [(rnd.uniform(-5, -3), rnd.uniform(-2.5, -1.5))])
    m.done(name)


# ---------------------------------------------------------------- village
def village(name, seed, windmill):
    rnd = random.Random(seed)
    m = Model(name, f"Terrain tile {name}: a village on a lane across the tile: cottages with red gable roofs, "
                    + ("a windmill, " if windmill else "a church tower, a pond, ") + "gardens and trees.", TILE_MATS)
    # ground: a lane y -0.35..0.35 across, meadow above and below, a few garden strips
    m.rect(-8, 8, -0.35, 0.35, "Lane")
    xs = splits(rnd, -8, 8, 2, 3.5)
    for i in range(len(xs) - 1):
        for (y0, y1) in ((-3.0, -0.35), (0.35, 2.7)):
            if rnd.random() < 0.3:
                field_cell(m, xs[i], xs[i + 1], y0, y1, "plough" if rnd.random() < 0.5 else "wheat", rnd)
            elif not windmill and i == 1 and y0 > 0:
                # the pond: water cell with sand rim strips
                px0, px1 = xs[i], xs[i + 1]
                m.rect(px0, px1, 0.35, 0.9, "Grass")
                m.rect(px0, px1, 2.2, 2.7, "Grass")
                m.rect(px0, px0 + 0.8, 0.9, 2.2, "Grass")
                m.rect(px1 - 0.8, px1, 0.9, 2.2, "Grass")
                m.rect(px0 + 0.8, px1 - 0.8, 0.9, 1.05, "Sand")
                m.rect(px0 + 0.8, px1 - 0.8, 2.05, 2.2, "Sand")
                m.rect(px0 + 0.8, px1 - 0.8, 1.05, 2.05, "Water", -0.05)
            else:
                m.rect(xs[i], xs[i + 1], y0, y1, "Grass")
    m.rect(-8, 8, 2.7, 3.0, "Grass")
    # cottages along both sides of the lane, roofs along the lane
    x = -7.2
    side = 1
    while x < 7.0:
        w = rnd.uniform(1.0, 1.4)
        if windmill and -1.6 < x + w / 2 < 1.6:
            x += 3.2
            continue
        d = rnd.uniform(0.7, 0.85)
        y = side * (0.35 + 0.2 + w / 2)
        m.house(x + d / 2, y, w, d, False)
        if rnd.random() < 0.5:
            m.tree(x + w + 0.35, y + side * 0.6, rnd.uniform(0.3, 0.38), rnd)
        x += d + rnd.uniform(0.6, 1.3)
        side = -side
    if windmill:
        # the windmill at the lane's middle, its sails facing down the screen (static)
        m.add("add mesh cone --name Mill --vertices 8 --radius1 0.55 --radius2 0.36 --depth 1.5 --location 0 1.4 0.75",
              "select Mill", "active Mill", "mode edit", 'select face where "normal.z < -0.9"', "delete only-faces",
              "mode object", "material assign Wall")
        m.add("add mesh cone --name Cap --vertices 8 --radius1 0.46 --radius2 0 --depth 0.5 --location 0 1.4 1.75",
              "select Cap", "active Cap", "mode edit", 'select face where "normal.z < -0.9"', "delete only-faces",
              "mode object", "material assign Roof")
        for k, a in enumerate((20, 110)):
            m.box(0, 0.86, 1.55, 2.3, 0.07, 0.24, "Stone", "Sail", rot=(0, a, 0))
        m.box(0, 0.9, 1.55, 0.16, 0.16, 0.16, "Plank", "Hub")
    else:
        # a church: nave and a square tower with a pyramid roof
        cx = rnd.choice([-4.6, 4.6])
        m.house(cx, -1.75, 1.8, 1.0, False, wall="Stone", chimney=False)
        m.box(cx, -0.55, 0.7, 0.62, 0.62, 1.4, "Stone", "Tower", drop_bottom=True)
        m.add(f"add mesh cone --name Spire --vertices 4 --radius1 0.5 --radius2 0 --depth 0.7 --location {cx:.2f} -0.55 1.75 --rotation 0 0 45",
              "apply --rotation", "select Spire", "active Spire", "mode edit", 'select face where "normal.z < -0.9"',
              "delete only-faces", "mode object", "material assign Roof")
    for k in range(4):
        m.tree(rnd.uniform(-7.5, 7.5), rnd.choice([-2.4, 2.2]), rnd.uniform(0.32, 0.45), rnd)
    far_hedge(m, seed, [(-0.6, 0.6)])
    m.done(name)


# ---------------------------------------------------------------- woods
def woods(name, seed, floor="Moss"):
    rnd = random.Random(seed)
    m = Model(name, f"Terrain tile {name}: a wood of round trees and pines on a mossy floor, a clearing with a "
                    "woodcutter's hut and a track.", TILE_MATS)
    cx = rnd.uniform(-4, 4)
    # ground: moss floor, a clearing (meadow) and a track running from the clearing to one side
    m.rect(cx - 1.6, cx + 1.6, -1.2, 1.2, "Pasture" if floor == "Grass" else "Grass")
    m.rect(-8, cx - 1.6, -3.0, 2.7, floor)
    m.rect(cx + 1.6, 8, -3.0, 2.7, floor)
    m.rect(cx - 1.6, cx + 1.6, 1.2, 2.7, floor)
    tx0, tx1 = cx - 0.3, cx + 0.3
    m.rect(cx - 1.6, tx0, -3.0, -1.2, floor)
    m.rect(tx1, cx + 1.6, -3.0, -1.2, floor)
    m.rect(tx0, tx1, -3.0, -1.2, "Soil")
    m.rect(-8, 8, 2.7, 3.0, floor)
    m.house(cx + 0.5, 0.3, 1.0, 0.75, rnd.random() < 0.5, wall="Plank", chimney=True)
    pts = []
    tries = 0
    while len(pts) < 34 and tries < 3000:
        tries += 1
        x, y = rnd.uniform(-7.6, 7.6), rnd.uniform(-2.6, 2.5)
        if abs(x - cx) < 1.9 and -1.5 < y < 1.5:
            continue
        if abs(x - cx) < 0.6 and y < -1.0:
            continue
        if any((x - a) ** 2 + (y - b) ** 2 < 0.75 ** 2 for a, b in pts):
            continue
        pts.append((x, y))
    for x, y in pts:
        if rnd.random() < 0.35:
            m.pine(x, y, rnd.uniform(0.9, 1.25))
        else:
            m.tree(x, y, rnd.uniform(0.38, 0.52), rnd)
    m.done(name)


# ---------------------------------------------------------------- river
def river(name, seed):
    rnd = random.Random(seed)
    m = Model(name, f"Terrain tile {name}: a river 2 m wide across the middle (the gunboats' lane, y 0), sandy "
                    "banks with reeds, fields on both sides, a jetty.", TILE_MATS)
    # water: strips of 1 x 0.5 m, a few lighter (ripples), 0.06 below the ground
    for i in range(16):
        for j, (y0, y1) in enumerate(((-1.0, -0.5), (-0.5, 0.0), (0.0, 0.5), (0.5, 1.0))):
            ripple = rnd.random() < 0.18 and j in (1, 2)
            m.rect(-8 + i, -7 + i, y0, y1, "Ripple" if ripple else "Water", -0.06)
    m.rect(-8, 8, 1.0, 1.25, "Sand", -0.02)
    m.rect(-8, 8, -1.25, -1.0, "Sand", -0.02)
    for (y0, y1) in ((-3.0, -1.25), (1.25, 2.7)):
        xs = splits(rnd, -8, 8, 2, 3.2)
        last = None
        for i in range(len(xs) - 1):
            k = rnd.choice([q for q in ("wheat", "plough", "meadow", "pasture") if q != last])
            last = k
            field_cell(m, xs[i], xs[i + 1], y0, y1, k, rnd)
            if i > 0:
                m.hedge(xs[i] - 0.15, xs[i] + 0.15, y0 + (0.2 if y0 > 0 else 0), y1 - (0.2 if y0 < 0 else 0), seed + i)
    m.rect(-8, 8, 2.7, 3.0, "Grass")
    # reeds on the banks
    for k in range(12):
        x = rnd.uniform(-7.6, 7.6)
        y = rnd.choice([-1.12, 1.12])
        n = m.nm("Reed")
        m.add(f"add mesh cone --name {n} --vertices 5 --radius1 0.14 --radius2 0 --depth 0.42 --location {x:.2f} {y:.2f} 0.19",
              f"select {n}", f"active {n}", "mode edit", 'select face where "normal.z < -0.9"', "delete only-faces",
              "mode object", "material assign Leaf")
    # a jetty from the far bank (stops short of the boats' lane)
    jx = rnd.uniform(-6, 6)
    m.box(jx, 0.82, 0.04, 0.5, 0.75, 0.08, "Plank", "Jetty")
    for k in range(3):
        m.tree(rnd.uniform(-7.5, 7.5), rnd.choice([-1.8, 1.8]), rnd.uniform(0.35, 0.45), rnd)
    far_hedge(m, seed)
    m.done(name)


fields("fieldsA", 11)
fields("fieldsB", 23)
village("villageA", 5, windmill=False)
village("villageB", 9, windmill=True)
woods("woodsA", 31)
woods("woodsB", 47, floor="Grass")
river("riverA", 61)
river("riverB", 73)


# ---------------------------------------------------------------- game pieces
def gore_selects(n=8):
    """face selections for the even gores of an n-segment sphere (by the face centre's angle)"""
    # sectors [0,45), [90,135), [180,225), [270,315) of 8
    return ['select face where "pos.x > 0 && pos.y >= 0 && pos.y < pos.x"',
            'select face where "pos.x <= 0 && pos.y > 0 && -pos.x < pos.y" --extend',
            'select face where "pos.x < 0 && pos.y <= 0 && pos.y > pos.x" --extend',
            'select face where "pos.y < 0 && pos.x >= 0 && pos.x < -pos.y" --extend']


def balloon(name, a, b, crate):
    m = Model(name, f"A {'supply ' if crate else ''}balloon: an 8-gore envelope ({a} and {b} stripes), "
                    f"1.1 m across and 1.27 m tall, a skirt and a wicker basket{' with a supply crate' if crate else ''}. "
                    "Pivot at the envelope's centre.", sorted({a, b, "Canvas", "Wicker", "Wall", "Dark"}))
    m.add("add mesh uv-sphere --name Env --segments 8 --rings 6 --radius 0.55 --location 0 0 0",
          "scale 1 1 1.15", "apply --scale", "select Env", "active Env", f"material assign {b}", "mode edit",
          *gore_selects(), f"material assign {a}", "mode object")
    m.add("add mesh cone --name Skirt --vertices 8 --radius1 0.13 --radius2 0.26 --depth 0.24 --location 0 0 -0.66",
          "material assign Canvas")
    m.box(0, 0, -0.93, 0.32, 0.32, 0.24, "Wicker", "Basket")
    if crate:
        m.box(0, 0, -1.15, 0.26, 0.26, 0.2, "Dark", "Crate")
    m.done(name)


balloon("balloon", "Roof", "Canvas", False)
balloon("supply", "Gold", "Canvas", True)

# the gunboat's hull (sails along X in the game: placed with a yaw of +-90), pivot at the waterline centre
m = Model("boat", "A river gunboat, 0.7 x 1.9 m: a grey hull with a pointed bow (front -Y), a red bow stripe, a cream "
                  "cabin and a funnel; its turret is a separate piece (turret.txt). Pivot at the waterline centre.",
          ["Metal", "Steel", "Wall", "Dark", "Roof"])
