# the pop: a 3D star of spikes along the icosahedron's vertex directions round a hot core (unlit)
m = Model("pop", "A hit pop: a core ball 0.6 m across with twelve spikes 0.55 m long round it (unlit glow). "
                 "Pivot at its centre; the game scales it up and away.", ["Core", "Hot", "Flame"])
m.add("add mesh ico-sphere --name Core --subdivisions 1 --radius 0.3 --location 0 0 0", "material assign Core")
phi = (1 + 5 ** 0.5) / 2
dirs = []
for a in (-1, 1):
    for b in (-phi, phi):
        dirs += [(0, a, b), (a, b, 0), (b, 0, a)]
for k, (dx, dy, dz) in enumerate(dirs):
    l = math.sqrt(dx * dx + dy * dy + dz * dz)
    dx, dy, dz = dx / l, dy / l, dz / l
    ax = math.degrees(math.acos(max(-1, min(1, dz))))
    bz = math.degrees(math.atan2(dx, -dy))
    r = 0.52
    n = m.nm("Spike")
    m.add(f"add mesh cone --name {n} --vertices 4 --radius1 0.13 --radius2 0 --depth 0.55 --location 0 0 0.275",
          "apply --location", f"translate 0 0 {0.18:.2f}", "apply --location",
          f"set rotation {ax:.2f} 0 {bz:.2f}", "apply --rotation",
          f"material assign {'Hot' if k % 3 else 'Flame'}")
m.done("pop")

